#!/usr/bin/env python3
"""Self-contained R3 Schiffer/Pompeiu computer-assisted verifier.

All mathematical centre data and stage sources are embedded in this file.
The verifier constructs its approximate inverse and recomputes every interval
stage; it does not accept saved PASS receipts. It prints PROVED only after
complete coverage, finite guards, radii inequalities and reconstruction gates.

Dependencies: Python 3, numpy, scipy, python-flint 0.9.0, and gcc on 64-bit Linux.
At most four single-thread workers run, all at nice 19. The C accelerator uses
the installed FLINT library and checks its ABI before arithmetic.
"""
