def need(ok,message):
    if not ok:raise ArithmeticError(message)


def has_progress(pending,active,completed):
    # Completion may empty the active set while making a pending child ready.
    return bool(active) or not pending or any(t['deps'].issubset(completed) for t in pending)


def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--workdir',help='new or empty directory for recomputed artifacts; default a new /tmp directory')
    ap.add_argument('--output',default='verify_r3_certificate.json')
    ap.add_argument('--jobs',type=int,default=4)
    ap.add_argument('--slots-file',help='optional integer file limiting active workers, from 1 through --jobs')
    ap.add_argument('--max-seconds',type=int,default=28800)
    args=ap.parse_args();need(1<=args.jobs<=4,'jobs must be between one and four')
    need(args.max_seconds>0,'positive runtime limit required')
    for key in ('OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS'):os.environ[key]='1'
    if hasattr(os,'getpriority'):os.nice(max(0,19-os.getpriority(os.PRIO_PROCESS,0)))
    started=time.monotonic();active={};completed=[];root=None
    def on_signal(signum,frame):raise InterruptedError('verification interrupted')
    signal.signal(signal.SIGTERM,on_signal)
    try:
        data=zlib.decompress(base64.b85decode(''.join(PACKED.split())))
        need(hashlib.sha256(data).hexdigest()==PAYLOAD_SHA256,'embedded payload integrity')
        payload=json.loads(data)
        if args.workdir:
            root=Path(args.workdir).resolve();root.mkdir(parents=True,exist_ok=True)
            need(not any(root.iterdir()),'workdir must be empty; old receipts are not accepted')
        else:root=Path(tempfile.mkdtemp(prefix='r3_proof_replay_'))
        for name,encoded in payload['files'].items():
            need(Path(name).name==name,'payload path must be a single filename')
            content=base64.b64decode(encoded);need(hashlib.sha256(content).hexdigest()==payload['sha256'][name],'asset hash')
            (root/name).write_bytes(content)
        (root/'logs').mkdir()
        import flint
        need(flint.__version__=='0.9.0','this frozen replayer requires python-flint 0.9.0')
        libs=Path(flint.__file__).parent.parent/'python_flint.libs'
        matches=list(libs.glob('libflint-*.so.*'));need(len(matches)==1,'unique installed FLINT shared library')
        compiler=shutil.which('gcc');need(compiler is not None,'gcc is required for the embedded interval accelerator')
        cmd=[compiler,'-O2','-fno-fast-math','-ffp-contract=off','-fPIC','-shared','coeff3_native.c',str(matches[0]),
             '-Wl,-rpath,'+str(libs),'-lm','-o','coeff3_native.so']
        built=subprocess.run(cmd,cwd=root,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,timeout=60)
        need(built.returncode==0,'native compilation failed: '+built.stdout[-2000:])
        print('REPLAY_WORKDIR',root,flush=True)
        matrix='hybrid_M180_S64_matrix.npz';center='refined_M180_step1.json';scale='hybrid_M120_S64.npz'
        tasks=[]
        def task(name,deps,module,*argv):tasks.append({'name':name,'deps':set(deps),'module':module,'argv':list(argv)})
        task('matrix',[],'prepare_matrix.py')
        task('residual',[],'certify_residual.py',center,'--native','--bits','1536','--output','residual_refined_step1_native')
        task('taylor',[],'prepare_shape_far.py')
        task('principal',['matrix'],'certify_principal.py','--center',center,'--scale-center',scale,'--matrix',matrix,'--output','principal_M180.json')
        task('jac_g',['principal'],'interval_jacobian.py','--center',center,'--scale-center',scale,'--matrix',matrix,'--kind','g','--start','0','--stop','180','--output','interval_M180_g.json')
        task('shape_all',['principal'],'certify_shape_columns.py','--center',center,'--scale-center',scale,'--matrix',matrix,'--columns','principal_M180.columns.npz','--max-n','518','--output','shape_columns_all.json')
        task('finite_matrix',['matrix'],'certify_finite_matrix.py',matrix,'--output','finite_matrix_certificate.json')
        for start,stop in ((0,20),(20,40),(40,60),(60,80)):
            task('g_near_'+str(start),['principal'],'certify_g_near.py','--start',str(start),'--stop',str(stop),'--output','g_near_'+str(start)+'.json')
        task('jac_shape',['principal'],'interval_jacobian.py','--center',center,'--scale-center',scale,'--matrix',matrix,'--kind','shape','--start','1','--stop','181','--output','interval_M180_shape.json')
        task('axis',['taylor'],'axis_factor.py')
        task('g_envelopes',['principal'],'certify_envelopes.py','--finite','--output','g_envelopes.json')
        task('shape_far',['g_envelopes','axis'],'certify_shape_far.py','--N','520','--output','shape_far_certificate.json')
        deps=[t['name'] for t in tasks]
        task('assemble',deps,'assemble_certificate.py','--output','certificate_r3.json','--shape','shape_columns_all.json',
             '--g-near','g_near_0.json','g_near_20.json','g_near_40.json','g_near_60.json')
        pending=list(tasks);last_status=0.
        while pending or active:
            need(time.monotonic()-started<args.max_seconds,'verification runtime limit exceeded')
            limit=args.jobs
            if args.slots_file:
                limit=int(Path(args.slots_file).read_text().strip());need(1<=limit<=args.jobs,'invalid slots-file value')
            for t in list(pending):
                if len(active)>=limit:break
                if not t['deps'].issubset(completed):continue
                log=root/'logs'/(t['name']+'.log');handle=log.open('w')
                command=[sys.executable,'-I','-O',str(root/'_worker.py'),t['module'],*t['argv']]
                proc=subprocess.Popen(command,cwd=root,stdout=handle,stderr=subprocess.STDOUT,env=os.environ.copy())
                active[t['name']]=(proc,handle,log);pending.remove(t)
                print('START',t['name'],flush=True)
            for name,(proc,handle,log) in list(active.items()):
                code=proc.poll()
                if code is None:continue
                handle.close();del active[name]
                if code:
                    excerpt=log.read_text(errors='replace')[-2200:]
                    raise ArithmeticError('stage '+name+' exited '+str(code)+'; '+excerpt)
                completed.append(name);print('DONE',name,flush=True)
            need(has_progress(pending,active,completed),'verification dependency deadlock')
            if time.monotonic()-last_status>=30:
                print('RUNNING',','.join(active),'elapsed',round(time.monotonic()-started),flush=True);last_status=time.monotonic()
            if active:time.sleep(1)
        for name,digest in payload['sha256'].items():
            need(hashlib.sha256((root/name).read_bytes()).hexdigest()==digest,'embedded source or input changed during replay: '+name)
        result=json.loads((root/'certificate_r3.json').read_text())
        need(result.get('status')=='ALL_EXISTENCE_GATES_PASSED','final existence gates did not pass')
        result.update({'status':'PROVED','replay_workdir':str(root),'replay_seconds':time.monotonic()-started,
                       'verifier_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
                       'embedded_payload_sha256':PAYLOAD_SHA256,'completed_stages':completed,
                       'scope':'Local computer-assisted existence certificate; all data and stages recomputed in this run.'})
        Path(args.output).write_text(json.dumps(result,indent=2)+'\n')
        print('PROVED',flush=True);print('CERTIFICATE',Path(args.output).resolve(),flush=True)
        return 0
    except BaseException as exc:
        print('NOT_CERTIFIED',str(exc),flush=True)
        return 2
    finally:
        for proc,handle,log in active.values():
            if proc.poll() is None:proc.terminate()
        for proc,handle,log in active.values():
            try:proc.wait(timeout=15)
            except subprocess.TimeoutExpired:proc.kill();proc.wait()
            handle.close()


if __name__=='__main__':raise SystemExit(main())
